// UUIDv7 (RFC 9562): time-ordered ids generated by the app, never by the database (club-ddl rule 2).
// Web Crypto's getRandomValues, not `node:crypto`, so the member app's bundle can carry it (T-0033).

export function uuidv7(now: Date = new Date()): string {
  const ms = BigInt(now.getTime());
  const b = globalThis.crypto.getRandomValues(new Uint8Array(16));
  b[0] = Number((ms >> 40n) & 0xffn);
  b[1] = Number((ms >> 32n) & 0xffn);
  b[2] = Number((ms >> 24n) & 0xffn);
  b[3] = Number((ms >> 16n) & 0xffn);
  b[4] = Number((ms >> 8n) & 0xffn);
  b[5] = Number(ms & 0xffn);
  b[6] = (b[6]! & 0x0f) | 0x70; // version 7
  b[8] = (b[8]! & 0x3f) | 0x80; // RFC 4122 variant
  const h = Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

export const isUuid = (s: string): boolean => /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(s);

/** Milliseconds since epoch encoded in a v7 id. */
export function uuidv7Time(id: string): number {
  return Number(BigInt(`0x${id.replace(/-/g, '').slice(0, 12)}`));
}
